files.patch:
@@ -498,6 +498,2 @@
-        // This is called from a C1 method's scalarized entry point.
-        // Use save_live_registers_except_r2 so Z_R2's frame slot is NOT
-        // recorded in the OopMap as a callee-saved live oop.  The GC must
-        // not visit that slot: before the call it holds an arbitrary live
-        // argument, and after the call it holds the result we want to keep.
-        OopMap* map = save_live_registers_except_r2(sasm);
+        // This is called from a C1 method's scalarized entry point
+        OopMap* map = save_live_registers(sasm);
@@ -509,3 +505,1 @@
-        // Result (array of buffered value objects) is returned in Z_R2.
-        // Use restore_live_registers_except_r2 so the result is not overwritten.
-        int call_offset = __ call_RT(Z_R2, noreg, entry, method);
+        int call_offset = __ call_RT(Z_R14, noreg, entry, method);
@@ -514,2 +508,3 @@
-        restore_live_registers_except_r2(sasm);
-        __ verify_oop(Z_R2);  // Z_R2: an array of buffered value objects
+        restore_live_registers(sasm);
+        __ z_lgr(Z_R1_scratch, Z_R14);
+        __ verify_oop(Z_R1_scratch);  // Z_R1_scratch: an array of buffered value objects

@@ -1118,25 +1118,1 @@
-    untested("remove_activation: InlineTypeReturnedAsFields");
-    NearLabel skip, not_null;
-    z_ltgr(Z_tos, Z_tos);
-    z_brne(not_null);
-    // Returned value is null: zero all return registers since they may hold oop fields.
-    z_lghi(Z_ARG2, 0);
-    z_lghi(Z_ARG3, 0);
-    z_lghi(Z_ARG4, 0);
-    z_lghi(Z_ARG5, 0);
-    z_brul(skip);
-    bind(not_null);
-
-    // Check if we are returning a non-null inline type and load its fields into registers.
-    test_oop_is_not_inline_type(Z_tos, Z_R1_scratch, skip, /* can_be_null= */ false);
-
-    // Load fields from a buffered value with an inline class specific handler.
-    load_klass(Z_R1_scratch, Z_tos);
-    z_lg(Z_R1_scratch, Address(Z_R1_scratch, InlineKlass::adr_members_offset()));
-    z_lg(Z_R1_scratch, Address(Z_R1_scratch, InlineKlass::unpack_handler_offset()));
-    // Unpack handler can be null if inline type is not scalarizable in returns.
-    z_ltgr(Z_R1_scratch, Z_R1_scratch);
-    z_bre(skip);
-    z_basr(Z_R14, Z_R1_scratch);
-
-    bind(skip);
+    stop("implement function InterpreterMacroAssembler::remove_activation");
